begin;
select no_plan();
create function pg_temp.expect_error(command text,expected text) returns text language plpgsql as $$ declare caught text; begin
 begin execute command; exception when others then caught:=sqlerrm; end;
 if caught is null or position(expected in caught)=0 then raise exception 'Expected %, got % for %',expected,coalesce(caught,'SUCCESS'),command; end if;
 return ok(true,'Rejected with '||expected); end $$;
select ok((select count(*)=3 and bool_and(status='requested' and scheduled_start_at is null) from public.appointments),'three legacy requests remain unconfirmed');
select ok((select count(*)=0 from public.appointment_change_requests),'no fabricated change history');
select ok((select last_message_seq=3 and client_read_seq=0 and staff_read_seq=0 and context_request_id is not null and context_order_id is null from public.concierge_requests where id='f6910000-0000-0000-0000-000000000001'),'sequence/context backfill and unknown reads preserve history');
select ok((select array_agg(message_seq order by id)=array[1,2,3]::bigint[] from public.concierge_messages),'stable timestamp/ID tie sequence');
set local role service_role;
select set_config('app.phase6.trusted','true',true);
select set_config('tcc.atelier_rpc','true',true);
select set_config('request.jwt.claim.role','postgres',true);
select pg_temp.expect_error($q$update public.appointments set status='confirmed' where id='f6900000-0000-0000-0000-000000000001'$q$,'appointment_rpc_required');
select pg_temp.expect_error($q$update public.concierge_requests set staff_read_seq=3 where id='f6910000-0000-0000-0000-000000000001'$q$,'conversation_rpc_required');
select pg_temp.expect_error($q$insert into public.concierge_messages(request_id,sender_type,sender_id,sender_name,message) values('f6910000-0000-0000-0000-000000000001','concierge',null,'TCC Concierge','GUC fake staff')$q$,'staff_message_rpc_required');
select pg_temp.expect_error($q$insert into public.concierge_messages(request_id,sender_type,sender_id,sender_name,message) values('f6910000-0000-0000-0000-000000000001','customer','f3000000-0000-0000-0000-000000000002','Client','Wrong owner')$q$,'invalid_sender');
select pg_temp.expect_error($q$update public.concierge_messages set message='overwrite'$q$,'immutable_atelier_record');
select pg_temp.expect_error($q$delete from public.concierge_messages$q$,'immutable_atelier_record');
select pg_temp.expect_error($q$insert into public.concierge_requests(reference_code,customer_id,category,subject,message,related_request_id) values('FAKE-CONTEXT','f3000000-0000-0000-0000-000000000001','general_enquiry','spoofed context','message','TCC-REQ-000019')$q$,'not_found');
select public.request_appointment_change('f3000000-0000-0000-0000-000000000001','f6900000-0000-0000-0000-000000000001','reschedule','2027-01-09','afternoon','Legacy works');
select ok((select lock_version=2 from public.appointments where id='f6900000-0000-0000-0000-000000000001'),'legacy change increments appointment version');
select pg_temp.expect_error($q$update public.appointment_change_requests set status='approved'$q$,'review_rpc_required');
select public.create_customer_concierge_request('f3000000-0000-0000-0000-000000000001','{"category":"general_enquiry","subject":"Legacy creation","message":"Legacy valid body","related_request_id":"TCC-REQ-000014"}');
select public.add_customer_concierge_message('f3000000-0000-0000-0000-000000000001','f6910000-0000-0000-0000-000000000001','Legacy reply works');
select ok((select last_message_seq=4 from public.concierge_requests where id='f6910000-0000-0000-0000-000000000001'),'legacy reply allocates sequence atomically');
select public.submit_public_fitting_request('f3000000-0000-0000-0000-000000000001','{"customer_name":"Local client","email":"local@example.invalid","phone":"000000","appointment_type":"measurement","preferred_date":"2027-01-08","preferred_time":"morning"}');
reset role;
select * from finish();
rollback;
